{"path": "/tmp/sv-f33e09cef49e4c82a486cd10ee0a97b4/Components/Chat/MessageInput.razor", "file_text": "<div class="message-input-container">
    <textarea @bind="text" @bind:event="oninput" @onkeydown="HandleKeyDown"
              placeholder="@Placeholder" rows="2"></textarea>
    <button class="send-btn" @onclick="Submit" disabled="@string.IsNullOrWhiteSpace(text)">
        @ButtonText
    </button>
</div>

@code {
    [Parameter] public string Placeholder { get; set; } = "Type a message...";
    [Parameter] public string ButtonText { get; set; } = "Send";
    [Parameter] public EventCallback<string> OnSubmit { get; set; }

    private string text = "";

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter" && !e.ShiftKey)
        {
            await Submit();
        }
    }

    private async Task Submit()
    {
        var trimmed = text.Trim();
        if (string.IsNullOrEmpty(trimmed)) return;
        text = "";
        await OnSubmit.InvokeAsync(trimmed);
    }
}
"}

