    {
        <ThreadPanel RootMessage="threadRootMessage"
                     Messages="threadMessages"
                     OnClose="CloseThread"
                     OnReply="SendThreadReply"
                     OnReact="args => HandleReaction(args.MessageId, args.Emoji)" />
    }
</div>

@code {
    private List<Channel> channels = [];
    private Channel? selectedChannel;
    private List<Message> messages = [];
    private bool isLoadingMore;
    private bool hasMoreMessages = true;
    private const int PageSize = 30;

    private bool isThreadOpen;
    private Message? threadRootMessage;
    private List<Message> threadMessages = [];

    private readonly Dictionary<int, int> replyCounts = [];

    private ElementReference messageListRef;
    private IJSObjectReference? jsModule;
    private DotNetObjectReference<Chat>? dotNetRef;
    private bool pendingScrollInit;

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannel(channels[0].Id);
        }
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            jsModule = await JS.InvokeAsync<IJSObjectReference>(
                "import", "./Components/Pages/Chat.razor.js");
            dotNetRef = DotNetObjectReference.Create(this);
        }

        if (pendingScrollInit && jsModule is not null && dotNetRef is not null)
        {
            pendingScrollInit = false;
            await jsModule.InvokeVoidAsync("initMessageList", messageListRef, dotNetRef);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        selectedChannel = channels.FirstOrDefault(c => c.Id == channelId);
        if (selectedChannel is null) return;

        messages = [];
        hasMoreMessages = true;
        replyCounts.Clear();
        CloseThread();

        await LoadMessages();
        await ChatService.MarkChannelReadAsync(channelId);

        var idx = channels.FindIndex(c => c.Id == channelId);
        if (idx >= 0)
        {
            channels[idx] = channels[idx] with { UnreadCount = 0 };
        }

        pendingScrollInit = true;
    }

    private async Task LoadMessages()
    {
        if (selectedChannel is null || isLoadingMore) return;

        isLoadingMore = true;
        StateHasChanged();

        var loaded = await ChatService.GetMessagesAsync(
            selectedChannel.Id, messages.Count, PageSize);

        if (loaded.Count < PageSize)
            hasMoreMessages = false;

        messages.InsertRange(0, loaded);
        UpdateReplyCounts(loaded);
        isLoadingMore = false;
    }

    [JSInvokable]
    public async Task OnScrolledToTop()
    {
        if (!hasMoreMessages || isLoadingMore || selectedChannel is null) return;

        double previousHeight = 0;
        if (jsModule is not null)
            previousHeight = await jsModule.InvokeAsync<double>("getScrollHeight", messageListRef);

        await LoadMessages();
        StateHasChanged();

        await Task.Yield();
        if (jsModule is not null && previousHeight > 0)
        {
            await jsModule.InvokeVoidAsync("preserveScrollPosition", messageListRef, previousHeight);
        }
    }

    private async Task SendMessage(string content)
    {
        if (selectedChannel is null) return;

        var message = await ChatService.SendMessageAsync(selectedChannel.Id, content, null);
        messages.Add(message);

        await ScrollToBottom();
    }

    private async Task HandleReaction(int messageId, string emoji)
    {
        await ChatService.AddReactionAsync(messageId, emoji);
        AddReactionLocally(messageId, emoji);
    }

    private void AddReactionLocally(int messageId, string emoji)
    {
        var msg = messages.FirstOrDefault(m => m.Id == messageId)
                  ?? threadMessages.FirstOrDefault(m => m.Id == messageId)
                  ?? (threadRootMessage?.Id == messageId ? threadRootMessage : null);
        if (msg is null) return;

        var existing = msg.Reactions.FirstOrDefault(r => r.Emoji == emoji);
        if (existing is not null)
        {
            if (!existing.Users.Contains("You"))
                existing.Users.Add("You");
        }
        else
        {
            msg.Reactions.Add(new Reaction(emoji, ["You"]));
        }
    }

    private async Task OpenThread(int messageId)
    {
        threadRootMessage = messages.FirstOrDefault(m => m.Id == messageId);
        if (threadRootMessage is null) return;

        threadMessages = await ChatService.GetThreadAsync(messageId);
        replyCounts[messageId] = threadMessages.Count;
        isThreadOpen = true;
    }

    private void CloseThread()
    {
        isThreadOpen = false;
        threadRootMessage = null;
        threadMessages = [];
    }

    private async Task SendThreadReply(string content)
    {
        if (threadRootMessage is null || selectedChannel is null) return;

        var reply = await ChatService.SendMessageAsync(
            selectedChannel.Id, content, threadRootMessage.Id);
        threadMessages.Add(reply);
        replyCounts[threadRootMessage.Id] = threadMessages.Count;
    }

    private int GetReplyCount(int messageId) =>
        replyCounts.TryGetValue(messageId, out var count) ? count : 0;

    private void UpdateReplyCounts(List<Message> loaded)
    {
        foreach (var msg in loaded)
        {
            if (msg.ReplyToId is int rootId)
            {
                replyCounts.TryGetValue(rootId, out var current);
                replyCounts[rootId] = current + 1;
            }
        }
    }

    private async Task ScrollToBottom()
    {
        await Task.Yield();
        if (jsModule is not null)
        {
            await jsModule.InvokeVoidAsync("scrollToBottom", messageListRef);
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (jsModule is not null)
        {
            try
            {
                await jsModule.InvokeVoidAsync("dispose");
                await jsModule.DisposeAsync();
            }
            catch (JSDisconnectedException) { }
        }
        dotNetRef?.Dispose();
    }
